asted-chicken-creamy-walnut-sauce	mealdb:53268	[{"id": "a4f6e064-1cd5-4ad5-a7a0-6759782b66e9", "name": "Куриные бёдра", "unit": "г", "grams": 400, "amount": 400, "ingredientId": "4408ccda-a27e-4db6-bc16-bef8099e89a5", "originalString": "400 г"}, {"id": "5225a19a-a763-44c7-af7c-25fef94913d9", "name": "Тмин", "unit": "г", "grams": 5, "amount": 5, "ingredientId": "d3ebda74-17c3-45b6-8ddd-82a44f0d652e", "originalString": "5 г"}, {"id": "fe394a25-40df-4f0a-b9e0-6d8f54f80abd", "name": "Паприка", "unit": "г", "grams": 2.5, "amount": 2.5, "ingredientId": "85045806-3a18-4d35-ad01-0230c0cb98d2", "originalString": "2.5 г"}, {"id": "dd49fb2a-2a7d-4740-8fd4-b536217302b8", "name": "Оливковое масло", "unit": "г", "grams": 30, "amount": 30, "ingredientId": "bbc2d001-a24b-49ee-b8ec-16e74e7297ef", "originalString": "30 г"}, {"id": "c56f0102-bd5a-481a-946e-7045e67ca59f", "name": "Пита", "unit": "г", "grams": 300, "amount": 300, "ingredientId": "f356588a-6c84-47c2-b111-7d352b793a75", "originalString": "300 г"}, {"id": "6bd7075f-ed0f-4584-a375-b4d1d0da6307", "name": "Куриный бульон", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "91e363d7-dd45-4ec9-9fec-998b79337f1d", "originalString": "50 г"}, {"id": "0564a5f3-1b34-45a2-93df-b43fc850bbbe", "name": "Грецкие орехи", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "943fa0a9-f332-42c8-927b-e37fb168b420", "originalString": "50 г"}, {"id": "23a34bcc-66ff-47c5-8887-bb6cd0828b3c", "name": "Лук", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "4c6015ce-c6bb-4495-8a13-ea54fd4567dd", "originalString": "50 г"}, {"id": "285632a0-2ee2-4f60-b0ff-6ac4a57e0867", "name": "Чеснок", "unit": "г", "grams": 100, "amount": 100, "ingredientId": "91e7717c-e7a3-40d1-ad26-cbf9f854ab62", "originalString": "100 г"}, {"id": "35247180-afd2-43b7-9872-9cb4a7c9e5de", "name": "Лёгкие сливки", "unit": "мл", "grams": 50, "amount": 50, "ingredientId": "9094dbf4-ecee-42f4-84b6-8fc7a4d96ee9", "originalString": "50 мл"}, {"id": "b7372017-82bc-4997-93