nipped fennel fronds.	4	\N	France	["перекус"]	t	https://www.bbcgoodfood.com/recipes/71600/prawn-and-fennel-bisque	mealdb:52922	[{"id": "08f0c76f-3ce8-46d6-aea0-23216e56f1c3", "name": "Креветки тигровые", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "0c0ece83-261b-41f5-ac29-c19baa8e1db4", "originalString": "50 г"}, {"id": "43134990-6594-4c45-9e3f-120bbe2ff58b", "name": "Оливковое масло", "unit": "г", "grams": 200, "amount": 200, "ingredientId": "bbc2d001-a24b-49ee-b8ec-16e74e7297ef", "originalString": "200 г"}, {"id": "32f8049e-3e65-4dde-8582-cd6adc7bbff1", "name": "Лук", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "4c6015ce-c6bb-4495-8a13-ea54fd4567dd", "originalString": "50 г"}, {"id": "778659e9-69d5-450e-ac99-d5dce9ac2e3f", "name": "Фенхель", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "d40fddb0-274e-4ca3-89ae-fd7a994e1a52", "originalString": "50 г"}, {"id": "56f452cb-98aa-4248-8662-fc0c4dd3286a", "name": "Морковь", "unit": "г", "grams": 100, "amount": 100, "ingredientId": "3ab14c63-202a-4334-b30c-9674ce7ef8fd", "originalString": "100 г"}, {"id": "2485e393-8982-4ddf-81ea-72aee9c346f8", "name": "Сухое белое вино", "unit": "мл", "grams": 50, "amount": 50, "ingredientId": "6d84be40-00a1-4bdd-8eda-7103f6aed423", "originalString": "50 мл"}, {"id": "02f210d9-15bb-4e27-b17e-2a46d43710ba", "name": "Бренди", "unit": "мл", "grams": 50, "amount": 50, "ingredientId": "5de60497-b26a-4b8a-90f9-cd0017975ab1", "originalString": "50 мл"}, {"id": "b81ad574-e17e-44d8-bae1-9b2e2f846e22", "name": "Томаты нарезанные", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "6bb88833-e4c2-4c34-aa82-b8d7869be930", "originalString": "50 г"}, {"id": "323b1f39-6181-42c6-b5df-1301187902b3", "name": "Рыбный бульон", "unit": "мл", "grams": 50, "amount": 50, "ingredientId": "ee2a3781-0de6-4bea-8d99-caccee356d5d", "originalString": "50 мл"}, {"id": "d0d869a9-4176-424f-a9a4-3a23856d2e38", "name": "Паприка", "unit": "г", "grams": 100, "amount": 100, "ingredientId