 months.	5	\N	Canadian	["перекус"]	t	https://canadianfoodfocus.org/recipes/classic-canadian-dishes-date-squares/	mealdb:53338	[{"id": "bd8de7d4-c599-49aa-91b2-8e2fab953e67", "name": "Финики без косточек", "unit": "г", "grams": 600, "amount": 600, "ingredientId": "88310d1a-b122-487e-b5b5-961d4a1ec643", "originalString": "600 г"}, {"id": "d21b7751-cef1-494e-89e7-7982f0c425b6", "name": "Вода", "unit": "мл", "grams": 240, "amount": 240, "ingredientId": "1eec42eb-3a97-4791-8cb2-da60cef6bc13", "originalString": "240 мл"}, {"id": "27b7cffc-e72a-41e6-805a-f143436dece9", "name": "Ваниль", "unit": "г", "grams": 360, "amount": 360, "ingredientId": "146f046f-d1cd-40c1-95f9-f1f1ccdfec5e", "originalString": "360 г"}, {"id": "83ecbb45-747b-4359-a129-d8f330a44372", "name": "Овсянка", "unit": "г", "grams": 480, "amount": 480, "ingredientId": "6e7245ea-2bad-4247-b932-193f1c52c966", "originalString": "480 г"}, {"id": "d03fe2a1-e7cb-49e1-88fe-8824b1bddc97", "name": "Мука универсальная", "unit": "г", "grams": 240, "amount": 240, "ingredientId": "7717640c-513a-49c1-aa49-aa8d896bc7d0", "originalString": "240 г"}, {"id": "a8813d2b-872c-48b7-acda-ef4ded261ce9", "name": "Коричневый сахар", "unit": "г", "grams": 240, "amount": 240, "ingredientId": "1d6fcd50-9e69-4015-9bea-1a9ae790690e", "originalString": "240 г"}, {"id": "c865dcd9-fa56-411a-9cb5-d6ef16e70726", "name": "Разрыхлитель", "unit": "г", "grams": 2.5, "amount": 2.5, "ingredientId": "972b3e3a-16f2-4ec2-b5e3-2bd543cca16d", "originalString": "2.5 г"}, {"id": "a5cbcff8-d9d1-43f4-be6c-d2cdd8b4baca", "name": "Соль", "unit": "г", "grams": 1.3, "amount": 1.3, "ingredientId": "3789cffa-31e4-49d0-bca4-aded4002f42c", "originalString": "1.3 г"}, {"id": "78c5a3f7-8615-4b88-b232-b3beba81dd05", "name": "Несолёное масло", "unit": "г", "grams": 240, "amount": 240, "ingredientId": "7649f0f5-1b77-434b-bacf-6c60e93fd78b", "originalString": "240 г"}]	["vegan", "vegetarian", "lactose-free"]	t	\N
