er 15 mins.	3	\N	Polish	["ужин"]	t	https://www.bbcgoodfood.com/recipes/braised-stuffed-cabbage	mealdb:53305	[{"id": "369e05e9-807e-41cf-b436-675751f6545e", "name": "Капустные листья", "unit": "г", "grams": 300, "amount": 300, "ingredientId": "b1fa497b-7acd-4cdd-986b-7b284db7bd6d", "originalString": "300 г"}, {"id": "fe3f080d-11c2-463a-87a5-86fbe8d1f4f6", "name": "Оливковое масло", "unit": "г", "grams": 30, "amount": 30, "ingredientId": "bbc2d001-a24b-49ee-b8ec-16e74e7297ef", "originalString": "30 г"}, {"id": "d8cd9af4-1178-4e7f-a594-9c7c7fba8769", "name": "Лук", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "4c6015ce-c6bb-4495-8a13-ea54fd4567dd", "originalString": "50 г"}, {"id": "20d631e1-df0b-40ff-b20e-889900944504", "name": "Розмарин", "unit": "г", "grams": 10, "amount": 10, "ingredientId": "b2ae0601-3650-4e55-9f46-881b1ef9d695", "originalString": "10 г"}, {"id": "e907eadb-61ed-4837-8894-9f0d3e639d0f", "name": "Сельдерей", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "a4b7203e-cf47-4297-8829-4be3c7270d19", "originalString": "50 г"}, {"id": "2e3e563a-9f1f-45fe-ae4a-8fc64626380b", "name": "Рис басмати", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "73161a81-741b-4518-ae40-ac98332a299b", "originalString": "50 г"}, {"id": "b3d0b1d1-2fcc-4884-8bf9-ec95d0e9e6d5", "name": "Варёный каштан", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "6e636f34-28ff-4f85-a304-ccb37a106ccf", "originalString": "50 г"}, {"id": "25049906-ee8d-4af5-98e8-a981107ca216", "name": "Клюква", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "12f461e5-5210-4ea9-8e9f-99f868c8e5aa", "originalString": "50 г"}, {"id": "7d55a74a-0261-49b1-85cd-8a9aeacbdb29", "name": "Овощной бульон", "unit": "мл", "grams": 50, "amount": 50, "ingredientId": "bff11d6b-d845-4500-9af2-b6760a6e6843", "originalString": "50 мл"}, {"id": "82fd0b66-713e-4aac-a0cf-aadc402933cd", "name": "Бальзамический уксус", "unit": "мл", "grams": 15, "amount": 15, "ingredientId": "c2cec43e-c68c-4