aking.com/2018/07/02/alfajores-the-best-cookies-from-uruguay/#recipe	mealdb:53320	[{"id": "0c7a1a6a-7f83-44f6-a722-5ac82896be3f", "name": "Масло", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "1338b99b-c8f0-44df-af06-d78808709d42", "originalString": "50 г"}, {"id": "bd000738-ccba-42b3-8a9b-fb0a99013b73", "name": "Сахар", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "f686d932-ccf2-4d50-9f23-2e0375fdd9d4", "originalString": "50 г"}, {"id": "e4f73378-feb6-4e76-b940-410a1cfd2a48", "name": "Яйцо", "unit": "шт", "grams": 55, "amount": 1, "ingredientId": "cab42edd-5e3a-4893-839e-9f4ef50c6cf0", "originalString": "1 шт"}, {"id": "dc892a20-831f-49a0-9504-ae3fa1155205", "name": "Мёд", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "64170819-df8c-49fa-b2ec-29fe5932623f", "originalString": "50 г"}, {"id": "a7729612-2f85-48a4-b56d-956bf8b88f7e", "name": "Мука", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "6b9d37d6-50b6-41f6-bc22-2376d8109821", "originalString": "50 г"}, {"id": "f52802bf-1361-4dad-abdb-9c019efae497", "name": "Кукурузный крахмал", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "41137d44-eccd-4d8e-b985-ca171a3b3a50", "originalString": "50 г"}, {"id": "54966c20-214b-4163-bfc9-c2f5e343d472", "name": "Какао-порошок", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "52b3d216-f8e2-4976-8b7e-cc395410eb7c", "originalString": "50 г"}, {"id": "895ebc92-ba15-4b54-a872-7d68cbe0af22", "name": "Разрыхлитель", "unit": "г", "grams": 5, "amount": 5, "ingredientId": "972b3e3a-16f2-4ec2-b5e3-2bd543cca16d", "originalString": "5 г"}, {"id": "6d744e57-26e0-4246-9f94-98fbf0fde813", "name": "Dulce de leche", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "6aee8b0d-e361-49fb-b868-7bd294249194", "originalString": "50 г"}, {"id": "cacd8463-1747-42c1-9bb2-955aea5baf9e", "name": "Шоколадное молоко", "unit": "мл", "grams": 50, "amount": 50, "ingredientId": "593a6015-3588-4b27-9c9d-53f7517f9dce", "originalString": "50 мл"}, {"i