eef mandi with salad or chutney.	8	\N	India	["ужин"]	t	\N	mealdb:53359	[{"id": "0a057e3a-aa9b-4125-8a84-ffee521d949b", "name": "Басмати рис", "unit": "г", "grams": 1000, "amount": 1000, "ingredientId": "5bc18ca7-b0a8-47ba-80c6-22b072615696", "originalString": "1000 г"}, {"id": "066e0ff1-a037-4609-ac00-d5f9413f1920", "name": "Говяжий бульон", "unit": "мл", "grams": 1200, "amount": 1200, "ingredientId": "e4abe98d-da0e-4159-8aed-2ce633951fc1", "originalString": "1200 мл"}, {"id": "d5dfc1d8-3575-4640-830d-accfb92e372c", "name": "Лук", "unit": "г", "grams": 100, "amount": 100, "ingredientId": "4c6015ce-c6bb-4495-8a13-ea54fd4567dd", "originalString": "100 г"}, {"id": "b2c49a9c-da66-450a-af85-29675bb84394", "name": "Чеснок", "unit": "г", "grams": 250, "amount": 250, "ingredientId": "91e7717c-e7a3-40d1-ad26-cbf9f854ab62", "originalString": "250 г"}, {"id": "e421a4fd-39f0-498c-a4dd-f5fa129e104e", "name": "Зелёный чили", "unit": "г", "grams": 100, "amount": 100, "ingredientId": "4d007358-35da-4232-bbd2-d5aa81f6f991", "originalString": "100 г"}, {"id": "48bfdc1b-408d-41c6-80c0-d2126dbf25ea", "name": "Помидор", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "56af0c35-84c3-4e11-8c83-f306df2b10eb", "originalString": "50 г"}, {"id": "2c3d18ff-d961-4d29-b50a-54be432d34c8", "name": "Соль", "unit": "г", "grams": 12.5, "amount": 12.5, "ingredientId": "3789cffa-31e4-49d0-bca4-aded4002f42c", "originalString": "12.5 г"}, {"id": "2f4f402e-4dc5-4011-8354-14ecfa240dd5", "name": "Масло", "unit": "г", "grams": 45, "amount": 45, "ingredientId": "1338b99b-c8f0-44df-af06-d78808709d42", "originalString": "45 г"}, {"id": "798c52c7-6a38-4042-8210-b537477f91ae", "name": "Куркума", "unit": "г", "grams": 50, "amount": 50, "ingredientId": "e9900362-e715-4c27-a1a7-e7f4837aec69", "originalString": "50 г"}, {"id": "9e899361-2801-4cbc-a751-ab141d9407a3", "name": "Кардамон", "unit": "г", "grams": 2.5, "amount": 2.5, "ingredientId": "5dd52155-0745-4004-84dd-6ef596f58f82", "originalString": "2.5 г"},